INSERT INTO teas (name, slug, phonetic_name, original_name, description, origin, tea_type, category, caffeine_level, brewing_temp_c, brewing_time_min, brewing_num_brews, brewing_instructions, characteristics, health_benefits, color_hex, oxidation_level, roast_level, flavor_x, flavor_y, source_type, source, owner_id, is_public, wikidata_qid) VALUES
  ('24 Flavors', '24-flavors', '', '二十四味', 'Cantonese herbal tea', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 0, 20, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Aged White Tea', 'aged-white-tea', '', '老白茶', 'White tea that has been naturally aged for several years (typically 3–20+). As white tea ages, its character transforms profoundly: the fresh floral and delicately sweet notes of youth deepen into rich honey, dried fruit, and woody complexity. Revered in Chinese tea culture for the saying "one year tea, three years medicine, seven years treasure" — aged white tea is believed to gain both flavour and therapeutic value with time.', 'Fujian, China', 'white', 'true_tea', 'low', 95, 5, 5, 'Use 5g per 150ml of water at 90–95°C — hotter than fresh white tea. Rinse once (10 seconds, discard) to awaken the aged leaves. First infusion: 20–30 seconds gongfu style, adding 10 seconds per subsequent steep. Can yield 8+ infusions. For older teas (7+ years), try simmering 5g in 500ml water for 5–10 minutes for a rich, warming cup.', ARRAY['Honey','Woody','Dried Fruit','Sweet']::text[], ARRAY['Rich in Antioxidants','Reduces Inflammation','Boosts Immune System','Aids Digestion']::text[], '#C8C4B0', 10, 5, 30, 15, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Asamushi', 'asamushi', '', '浅蒸し', 'type of sencha green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Assam', 'assam', '', '', 'Grown in the lush Brahmaputra river valley of northeastern India — the world''s largest tea-growing region. Assam is a robust, full-bodied black tea with a bold malty character, deep amber liquor, and the backbone of most classic British breakfast blends.', 'Assam, India', 'black', 'true_tea', 'high', 95, 4, 2, 'Use 1 tsp (2–3g) per 8oz (240ml) of near-boiling water. Steep for 3–5 minutes. Assam stands up beautifully to milk and sugar. The foundation of English Breakfast and Irish Breakfast blends. CTC (crush-tear-curl) Assam brews faster and stronger than whole-leaf.', ARRAY['Bold','Malty','Earthy']::text[], ARRAY['Rich in Antioxidants','Improves Energy Levels','Boosts Heart Health']::text[], '#8B4513', 90, 70, 85, 65, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Bai Jiguan tea', 'bai-jiguan-tea', '', '白雞冠', 'Well-known oolong tea of Wuyi', 'China', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Baimao Hou', 'baimao-hou', '', '白毛猴', 'green tea from the Taimu Mountains in Fujian Province, China', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ban Tian Yao tea', 'ban-tian-yao-tea', '', '半天腰', 'A rarely seen Mount Wuyi Oolong with a light smokey taste', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Bancha', 'bancha', '', '番茶', 'Japanese green tea', 'Japan', 'green', 'true_tea', 'low', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Baozhong', 'baozhong', '', '包種茶', 'famous Taiwan spring tea between green and oolong', 'Taiwan', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Biluochun', 'biluochun', '', '碧螺春', 'famous Chinese green tea from Dongting Mountains, near Suzhou', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Bu Zhi Chun tea', 'bu-zhi-chun-tea', '', '不知春', 'a rarely seen Mount Wuyi Oolong with a light taste', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ceylon', 'ceylon', '', '', 'Sri Lanka''s flagship black tea, named for the island''s colonial-era name. Grown across multiple high-altitude regions, Ceylon teas are known for their bright amber liquor, brisk character, and distinctive notes of citrus, cocoa, and spice with 50–90mg of caffeine per cup.', 'Sri Lanka', 'black', 'true_tea', 'high', 95, 4, 2, 'Use 1 tsp (2–3g) per 8oz (240ml) of near-boiling water. Steep for 3–4 minutes. Excellent with or without milk. Uva region teas (high altitude) have the most distinctive spicy character; Nuwara Eliya produces a lighter, more delicate cup.', ARRAY['Bold','Citrusy','Malty']::text[], ARRAY['Rich in Antioxidants','Improves Focus','Boosts Heart Health']::text[], '#8B4513', 90, 70, 73, 55, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Chamomile Mint', 'chamomile-mint', '', '', 'A soothing herbal infusion blending calming chamomile with refreshing peppermint. The gentle sweetness of chamomile flowers balances the cooling menthol of peppermint for a tisane that is both relaxing and invigorating.', 'Egypt / United States', 'tisane', 'tisane', 'none', 100, 5, 2, 'Use 1.5 tsp (3–4g) per 8oz (240ml) of boiling water. Steep covered for 5 minutes to trap the essential oils. The blend is forgiving — longer steeping intensifies without becoming bitter. Add honey to enhance sweetness.', ARRAY['Floral','Minty']::text[], ARRAY['Promotes Sleep & Relaxation','Aids Digestion']::text[], '#C0856A', 40, 30, 12, 10, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Chik-Cha', 'arrowroot-tea', '', '칡차', 'beverage made by infusing arrowroot roots', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Chrysanthemum Tea', 'chrysanthemum-tea', '', '菊花茶', 'beverage made by infusing dried flowers of chrysanthemum', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
