  ('Corn Tea', 'corn-tea', '', '옥수수차', 'beverage made by infusing roasted corn kernels', 'South Korea', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Daechu-Cha', 'daechu-cha', '', '대추차', 'traditional Korean beverage made by infusing dried jujube berries', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dafang tea', 'dafang-tea', '', '頂谷大方', 'Flat green tea from Anhui province (China), similar to Longjing', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Darjeeling', 'darjeeling', '', '', 'Often called the ''Champagne of Teas'', Darjeeling is grown in the misty Himalayan foothills of West Bengal at elevations up to 2,000m. Its famous muscatel character — a musky, grape-like sweetness — is unique in the tea world and protected by geographical indication.', 'Darjeeling, West Bengal, India', 'black', 'true_tea', 'high', 90, 3, 2, 'First flush: use water at 85–90°C and steep 2–3 minutes. Second flush: 90–95°C for 3–4 minutes. Best enjoyed without milk for first flush to appreciate the muscatel notes. Second flush pairs well with a splash of milk.', ARRAY['Floral','Fruity','Malty']::text[], ARRAY['Rich in Antioxidants','Boosts Heart Health','Improves Focus']::text[], '#8B4513', 90, 70, 62, 40, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dian Hong Jin Luo', 'dian-hong-jin-luo', '', '滇红金螺', 'Type of Chinese black tea', '', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dianhong', 'dianhong', '', '滇紅茶', 'type of Chinese black tea grown in Yunnan province', '', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dohwa-Cha', 'peach-blossom-tea', '', '도화차', 'traditional Korean beverage made by infusing the dried peach flowers', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Doncha', 'doncha', '', '돈차', 'Korean coin-shaped post-fermented tea', 'Korea', 'dark', 'true_tea', 'high', 95, 4, 8, '', '{}'::text[], '{}'::text[], '#6B4226', 40, 30, 78, 55, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dongfang meiren tea', 'dongfang-meiren-tea', '', '東方美人', 'oolong tea', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dragonwell (Long Jing)', 'dragonwell-long-jing', '', '龙井', 'China''s most celebrated green tea, named for a well in the hills of Hangzhou. Pan-fired in a hot wok to create its signature flat, sword-shaped leaves, Dragonwell has a clean chestnut sweetness, delicate vegetal notes, and a lingering finish prized by emperors for centuries.', 'Hangzhou, Zhejiang, China', 'green', 'true_tea', 'medium', 80, 2, 3, 'Use 3g per 200ml of water at 75–80°C. Steep for 1–2 minutes. The second and third infusions are often considered the most flavourful. Use a glass cup to watch the leaves unfurl — part of the traditional Dragonwell experience.', ARRAY['Grassy','Nutty','Sweet']::text[], ARRAY['Rich in Antioxidants','Improves Focus','Boosts Heart Health']::text[], '#7BA05B', 0, 10, 13, 7, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Dried Lime Tea', 'dried-lime-tea', '', 'شاي الليمون المجفف', 'A beverage that widely consumed in Iraq , Kuwait , Oman and United Arab Emirates.', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Duyun Maojian', 'duyun-maojian', '', '都匀毛尖', 'Chinese Green Tea Type', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Earl Grey', 'earl-grey', '', '', 'The world''s most recognisable flavoured tea — a classic black tea blend naturally scented with bergamot oil, named after the British Prime Minister Charles Grey. Its floral citrus fragrance is immediately distinctive.', 'United Kingdom', 'blend', 'blend', 'high', 95, 4, 1, 'Use 1 tsp (2–3g) per 8oz (240ml) of near-boiling water. Steep for 3–5 minutes depending on strength preference. Excellent with a splash of milk or a slice of lemon. Avoid boiling water to preserve the bergamot''s delicate aroma.', ARRAY['Citrusy','Bold']::text[], ARRAY['Rich in Antioxidants','Boosts Heart Health']::text[], '#B07D56', 40, 30, 43, 40, 'default', 'Teapp', NULL, TRUE, NULL),
  ('East Friesland Tea Blend', 'east-friesland-tea-blend', '', 'Ostfriesentee', 'A strong, traditional black tea blend from Ostfriesland, Germany. Primarily Assam tea with Ceylon, African, Java, Sumatra, and Darjeeling varieties. Designed to be enjoyed with cream (Sahne) and rock sugar (Kluntje).', 'Ostfriesland, Germany', 'blend', 'blend', 'high', 95, 4, 1, 'Place rock sugar (Kluntje) in the cup. Pour hot tea over the sugar, then add a spoonful of cream to the edge of the cup to form a Wulkje (small cloud). Do not stir — enjoy the layers: cream first, then the strong tea, then the sweetness.', ARRAY['Strong','Malty','Aromatic','Slightly bitter']::text[], '{}'::text[], '#B07D56', 80, 60, 60, 50, 'default', 'Teapp', NULL, TRUE, NULL),
  ('English Breakfast', 'english-breakfast', '', '', 'The quintessential British morning tea — a robust, full-bodied blend of Assam, Ceylon, and Darjeeling black teas, designed to be paired with milk, hold its own against a hearty breakfast, and provide a strong caffeine start to the day.', 'United Kingdom', 'blend', 'blend', 'high', 95, 4, 1, 'Use 1 tsp (2–3g) per 8oz (240ml) of near-boiling water. Steep for 3–4 minutes. Traditionally served with whole milk added to the cup first, then tea poured over. Sugar is optional. The ratio of teas in the blend varies by producer.', ARRAY['Bold','Malty']::text[], ARRAY['Rich in Antioxidants','Improves Energy Levels','Improves Focus']::text[], '#B07D56', 40, 30, 53, 50, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Fo Shou tea', 'fo-shou-tea', '', '佛手', 'A rarely seen Mount Wuyi Oolong', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Fukamushicha', 'fukamushicha', '', '深蒸し茶', 'kind of green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Fukuju', 'fukuju', '', '福寿', 'type of green tea', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Genmaicha', 'genmaicha', '', '玄米茶', 'Japanese green tea mixed with brown rice', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ginger Root', 'ginger-root', '', '', 'A warming and invigorating tisane brewed from dried slices of Zingiber officinale root. Sharp, fiery, and deeply aromatic, ginger tea has been used in traditional Ayurvedic and Chinese medicine for millennia as a remedy for nausea, poor digestion, and inflammation.', 'India, China & Caribbean', 'tisane', 'tisane', 'none', 100, 5, 2, 'Use 1 tsp (2–3g) of dried ginger root per 8oz (240ml) of boiling water. Steep for 5–10 minutes — longer brewing creates more heat. For fresh ginger, use 3–4 thin slices and simmer for 10 minutes. Add honey and a squeeze of fresh lemon to round out the spice beautifully.', ARRAY['Spicy','Sweet','Earthy']::text[], ARRAY['Aids Digestion','Reduces Inflammation','Boosts Immune System','Improves Energy Levels']::text[], '#C0856A', 40, 30, 35, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ginseng Tea', 'ginseng-tea', '', '人参茶', 'beverage made by infusing ginseng roots', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Goishicha', 'goishicha', '', '碁石茶', 'type of fermented tea', '', 'dark', 'true_tea', 'high', 95, 4, 8, '', '{}'::text[], '{}'::text[], '#6B4226', 40, 30, 78, 55, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Goji Tea', 'goji-tea', '', '枸杞茶', 'traditional Korean and Chinese beverage made by infusing dried goji berries or leaves', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Gokmul-Cha', 'seed-tea', '', '곡물차', 'traditional Korean beverages made of seeds of various plants', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Golden Monkey tea', 'golden-monkey-tea', '', '金猴茶', 'a fine black tea from Yunnan province', '', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Gunpowder Green', 'gunpowder-green', '', '珠茶', 'Named for its tightly rolled pellets that resemble old musket powder, this bold Chinese green tea from Zhejiang province unfurls dramatically in hot water. Its robust, slightly smoky character makes it one of the longest-lasting green teas in storage.', 'Zhejiang, China', 'green', 'true_tea', 'medium', 80, 3, 3, 'Use 1 tsp (3g) of pellets per 8oz (240ml) of water at 75–80°C. Steep for 2–3 minutes. Overbrewing will intensify bitterness. The traditional base for Moroccan Mint Tea — the pellets hold up well to the addition of sugar and mint.', ARRAY['Smoky','Bold','Earthy']::text[], ARRAY['Rich in Antioxidants','Boosts Immune System']::text[], '#7BA05B', 0, 10, 50, 40, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Gyeolmyeongja-Cha', 'gyeolmyeongja-cha', '', '결명자차', 'beverage made by infusing roasted sicklepod grains', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Gyepi-Cha', 'gyepi-cha', '', '계피차', 'herbal tea', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 0, 20, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Gyokuro', 'gyokuro', '', '玉露', 'Japan''s most prized green tea, shaded from sunlight for 20+ days before harvest. The reduced light signals the plant to produce extraordinary levels of L-theanine and chlorophyll, resulting in an intensely umami, sweet, and deeply complex cup known as ''jade dew''.', 'Uji & Yame, Japan', 'green', 'true_tea', 'high', 60, 2, 3, 'Use 5g per 150ml of water at 55–60°C — far cooler than any other tea. Steep for exactly 2 minutes without stirring. The low temperature extracts sweetness and umami while suppressing bitterness. Re-steep 2–3 times, slightly increasing temperature each time.', ARRAY['Umami','Sweet','Grassy']::text[], ARRAY['Rich in Antioxidants','Improves Focus','Boosts Heart Health','Rich in L-Theanine']::text[], '#7BA05B', 0, 10, 5, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Hibiscus', 'hibiscus', '', '', 'A vibrant ruby-red tisane brewed from the dried calyces of Hibiscus sabdariffa, known for its brilliant colour and tart, cranberry-like flavour. Packed with vitamin C and anthocyanins, hibiscus is one of the most visually striking and health-supporting teas in the world.', 'Egypt, Mexico & West Africa', 'tisane', 'tisane', 'none', 100, 5, 2, 'Use 1–2 tsp (2–4g) of dried flowers per 8oz (240ml) of boiling water. Steep for 5–7 minutes for maximum colour and flavour. Excellent served iced — refrigerate after brewing. Add honey or a cinnamon stick to balance the tartness. Known as ''karkadé'' in Egypt and ''agua de jamaica'' in Mexico.', ARRAY['Tart','Fruity','Floral']::text[], ARRAY['Rich in Antioxidants','Boosts Heart Health','Reduces Inflammation','Boosts Immune System']::text[], '#C0856A', 40, 30, 17, 10, 'default', 'Teapp', NULL, TRUE, NULL),
  ('High mountain tea', 'high-mountain-tea', '', '高山茶', 'varieties of oolong tea grown in Taiwan', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Hojicha', 'hojicha', '', '焙じ茶', 'Japanese green tea roasted over charcoal', 'Japan', 'green', 'true_tea', 'low', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Huang Guanyin tea', 'huang-guanyin-tea', '', '黄觀音茶', 'A new cultivar of Mount Wuyi Oolong', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Huang Mei Gui tea', 'huang-mei-gui-tea', '', '黃玫瑰', 'a very new Wuyi Oolong tea', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Huangjin Gui', 'huangjin-gui', '', '黃金桂', 'premium variety of Oolong from Anxi', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Huoshan Huangya tea', 'huoshan-huangya-tea', '', '霍山黄芽', 'yellow tea from Anhui province', 'People''s Republic of China', 'yellow', 'true_tea', 'medium', 80, 2, 3, '', '{}'::text[], '{}'::text[], '#E6C84E', 15, 15, 30, 18, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Irimushi', 'irimushi', '', '炒蒸し', 'type of sencha green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Jasmine Green Tea', 'jasmine-green', '', '茉莉花茶', 'Most famous scented tea in China. Tea base (most commonly green tea, also white, oolong, or black) infused with natural fragrance of jasmine blossoms through a layered absorption process. Subtly sweet and highly fragrant flavor. Initial gentle astringency followed by clean, sweet lingering finish. Fujian-produced jasmine tea has the best reputation in China.', 'Fujian, China (also Jiangsu, Jiangxi, Guangdong, Guangxi, Zhejiang)', 'blend', 'blend', 'medium', NULL, NULL, 1, 'Use 2g per 200ml of water at 80–85°C. Steep for 2–3 minutes. Never use boiling water — it damages the delicate jasmine aroma. Excellent for 2–3 infusions. Jasmine pearls (a rolled variety) are especially beautiful to watch unfurl in a glass cup.', ARRAY['Floral','Sweet','Grassy']::text[], ARRAY['Rich in Antioxidants','Reduces Stress & Anxiety','Promotes Sleep & Relaxation']::text[], '#B07D56', 40, 30, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Jin Fo tea', 'jin-fo-tea', '', '金佛茶', 'medium Wuyi Oolong tea', 'People''s Republic of China', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Jin Jun Mei tea', 'jin-jun-mei-tea', '', '金駿眉', 'type of black tea from the Wuyi Mountains in Fujian Province, China', '', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Junshan Yinzhen', 'junshan-yinzhen', '', '君山銀針;', 'One of China''s Ten Famous Teas and the most celebrated yellow tea in the world. Harvested exclusively from Junshan Island on Dongting Lake in Hunan, each batch uses only the tenderest first-flush buds plucked in a brief spring window. The distinctive sealed yellowing step (闷黄, mén huáng) gently mellows the leaves, yielding a cup that sits between green and white tea — less grassy than the former, with more body than the latter. Expect mellow sweetness, light grain, a whisper of apricot, and a clean lingering finish.', 'Junshan Island, Hunan, China', 'yellow', 'true_tea', 'low', 70, 3, 3, 'Use 3g per 150ml of water at 70–75°C — avoid boiling water, which will mask the subtle sweetness. Steep for 2–3 minutes. Use a glass vessel if possible to watch the silver needle buds dance upright as they unfurl. Can be re-steeped 2–3 times, each infusion revealing slightly different notes.', ARRAY['Sweet','Grassy','Floral','Nutty']::text[], ARRAY['Rich in Antioxidants','Aids Digestion','Reduces Inflammation','Boosts Immune System']::text[], '#E6C84E', 15, 15, 18, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Kamairicha tea', 'kamairicha-tea', '', '釜炒り茶', 'Japanese green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Kangra tea', 'kangra-tea', '', 'कांगड़ा चाय', 'black or green tea from the Kangra district, India', '', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Keemun', 'keemun', '', '祁門紅茶', 'famous Chinese black tea', 'People''s Republic of China', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
