  ('Kukicha', 'kukicha', '', '茎茶', 'Japanese tea blend', 'Japan', 'green', 'true_tea', 'low', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 40, 30, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Lady Grey', 'lady-grey', '', '', 'trademarked variation on Earl Grey tea', 'England', 'blend', 'true_tea', 'high', 90, 4, 1, '', '{}'::text[], '{}'::text[], '#B07D56', 40, 30, 40, 35, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Lapacho', 'lapacho', '', '', 'herbal tea made from a Central and South American tree''s bark', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 0, 20, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Lapsang Souchong', 'lapsang-souchong', '', '正山小種', 'The world''s first black tea, originating from the Wuyi Mountains in 1646. Its large leaves are withered and dried over smouldering pine wood fires, absorbing an intensely smoky, resinous character that has earned it the nickname ''the whiskey of black teas''.', 'Wuyi Mountains, Fujian, China', 'black', 'true_tea', 'medium', 95, 3, 2, 'Use 2g per 200ml of water at 90–95°C. Steep for 3–4 minutes. Avoid over-steeping to prevent bitterness. Best enjoyed without milk to fully appreciate the smoke. An acquired taste — loved passionately by those who appreciate it.', ARRAY['Smoky','Bold','Woody']::text[], ARRAY['Rich in Antioxidants','Reduces Inflammation','Aids Digestion']::text[], '#8B4513', 90, 70, 92, 65, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Lavender', 'lavender', '', '', 'A soothing floral tisane brewed from the dried buds of Lavandula angustifolia. With a delicate, perfumed sweetness and an unmistakable calming aroma, lavender tea has long been treasured in European herbal traditions as an aid to anxiety, insomnia, and restlessness.', 'Provence, France & Mediterranean', 'tisane', 'tisane', 'none', 95, 5, 2, 'Use 1 tsp (1–2g) of dried lavender buds per 8oz (240ml) of water at 90–95°C (avoid boiling — it can make lavender medicinal). Steep for 5 minutes. Pairs beautifully with honey or a slice of lemon. Excellent blended with chamomile for a deeper sleep-promoting effect.', ARRAY['Floral','Sweet','Creamy']::text[], ARRAY['Promotes Sleep & Relaxation','Reduces Stress & Anxiety','Reduces Inflammation']::text[], '#C0856A', 40, 30, 20, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Lotus Tea', 'lotus-tea', '', '연잎차', 'beverage made by infusing leaves, flowers, roots of lotus', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Maehwa-Cha', 'plum-blossom-tea', '', '매화차', 'traditional Korean beverage made by infusing the dried plum flowers', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Maesil-Cha', 'maesil-cha', '', '매실차', 'traditional Korean beverage made by diluting the maesil marmalade with water', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Maghrebi Mint Tea', 'maghrebi-mint-tea', '', 'أتاي', 'tea preparation and form of tea consumption in the Maghreb countries', 'Maghreb', 'tisane', 'tisane', 'medium', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Maojian tea', 'maojian-tea', '', '信陽毛尖', 'one of the top Chinese green teas', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Masala Chai', 'masala-chai', '', 'मसाला चाय', 'India''s beloved spiced tea, brewed strong with milk and a warming blend of cardamom, ginger, cinnamon, cloves, and black pepper. Deeply aromatic, invigorating, and comforting — masala chai is as much a ritual as a beverage, sold on every street corner in India.', 'India', 'blend', 'blend', 'high', 100, 5, 1, 'Simmer 1 tsp (2–3g) of strong black tea with 200ml of water and 200ml of whole milk. Crush and add spices: 3–4 cardamom pods, a cinnamon stick, 3 cloves, 2 slices of ginger, and 3–4 black peppercorns. Bring to a boil twice. Strain and sweeten with jaggery or sugar.', ARRAY['Spicy','Sweet','Malty','Creamy']::text[], ARRAY['Aids Digestion','Improves Energy Levels','Boosts Immune System','Reduces Inflammation']::text[], '#B07D56', 40, 30, 53, 27, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Matcha', 'matcha', '', '抹茶', 'A finely stone-ground powder made from shade-grown tencha leaves. Unlike all other teas, matcha is whisked into water rather than steeped — meaning you consume the entire leaf and all its nutrients. One of the most antioxidant-rich foods on earth.', 'Uji, Japan', 'green', 'true_tea', 'high', 80, 1, 3, 'Sift 1–2g of ceremonial grade matcha into a warmed bowl. Add 70–80ml of water at 75–80°C (never boiling). Whisk vigorously in a ''W'' or ''M'' motion until frothy. For usucha (thin tea) use 1g; for koicha (thick tea) use 3–4g and whisk slowly.', ARRAY['Umami','Grassy','Vegetal','Creamy']::text[], ARRAY['Rich in Antioxidants','Improves Focus','Supports Weight Management','Reduces Stress & Anxiety']::text[], '#7BA05B', 0, 10, 5, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Mecha tea', 'mecha-tea', '', '芽茶', 'Popular after-dinner Japanese green tea', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Meng Ding Huangya', 'meng-ding-huangya', '', '蒙顶黄芽', 'yellow tea from Mt. Meng', '', 'yellow', 'true_tea', 'medium', 80, 2, 3, '', '{}'::text[], '{}'::text[], '#E6C84E', 15, 15, 30, 18, 'default', 'Teapp', NULL, TRUE, NULL),
