  ('Mogwa-Cha', 'mogwa-cha', '', '모과차', 'traditional Korean beverage made by diluting the mogwa marmalade with water', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ogwa-Cha', 'ogwa-cha', '', '오과차', 'five-fruit tea', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Omija-Cha', 'omija-cha', '', '오미자차', 'traditional Korean beverage made by infusing dried magnolia berries', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Peppermint', 'peppermint', '', '', 'A crisp, cooling tisane made from the dried leaves of Mentha piperita — a natural hybrid of spearmint and watermint. One of the world''s most popular herbal teas, prized for its intensely clean menthol character, digestive benefits, and invigorating clarity.', 'Europe & North America', 'tisane', 'tisane', 'none', 100, 5, 2, 'Use 1–2 tsp (2–4g) of dried peppermint per 8oz (240ml) of boiling water. Steep covered for 5–7 minutes to trap the volatile menthol oils. Fresh peppermint leaves can be substituted — use 2–3 times the quantity. Peppermint does not turn bitter with extended steeping.', ARRAY['Minty','Sweet','Grassy','Refreshing']::text[], ARRAY['Aids Digestion','Reduces Stress & Anxiety','Boosts Immune System']::text[], '#C0856A', 40, 30, 5, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Persimmon Leaf Tea', 'persimmon-leaf-tea', '', '감잎차', 'traditional Korean beverage made by infusing dried leaves of persimmon', 'Korea', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ppuri-Cha', 'root-tea', '', '뿌리차', 'traditional Korean beverages made of roots, shoots, and barks of various plants', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Qilan tea', 'qilan-tea', '', '奇蘭', 'oolong tea from Mount Wuyi', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Rooibos', 'rooibos', '', 'rooibos', 'South Africa''s beloved ''red bush'' tea, made from the fermented leaves of Aspalathus linearis — a plant that grows exclusively in the Cederberg mountains. Naturally sweet, caffeine-free, and rich in aspalathin (a unique antioxidant found nowhere else in nature).', 'Cederberg Mountains, Western Cape, South Africa', 'tisane', 'tisane', 'none', 100, 5, 2, 'Use 1 tsp (2–3g) per 8oz (240ml) of boiling water. Steep for 5–10 minutes — unlike true teas, rooibos does not become bitter with extended steeping, only stronger. Excellent with or without milk, and naturally sweet enough to enjoy without sugar.', ARRAY['Sweet','Nutty','Earthy']::text[], ARRAY['Rich in Antioxidants','Boosts Heart Health','Lowers Cholesterol','Reduces Inflammation']::text[], '#C0856A', 40, 30, 38, 12, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ruanzhi tea', 'ruanzhi-tea', '', '軟枝', 'Variety of the tea plant processed into oolong', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Russian Caravan', 'russian-caravan', '', '', 'Blend of black teas transported to Europe by caravans', 'People''s Republic of China', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Sanyak-Cha', 'yam-tea', '', '산약차', 'beverage made by infusing yam roots', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Sayama tea', 'sayama-tea', '', '狭山茶', 'type of Japanese green tea leaves', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Sencha', 'sencha', '', '煎茶', 'Japan''s most beloved everyday green tea, accounting for nearly 80% of the country''s tea production. Grown in full sunlight and steamed immediately after harvest, Sencha has a fresh, vibrant green colour and a clean, grassy flavour with a pleasant astringency.', 'Shizuoka & Uji, Japan', 'green', 'true_tea', 'medium', 75, 2, 3, 'Use 1 tsp (roughly 3g) per 8oz (240ml) of water at 70–80°C. Steep for 1–2 minutes. Can be re-steeped up to 3 times, increasing steep time by 30 seconds each infusion. Cooler water and shorter times yield sweeter, more delicate cups.', ARRAY['Earthy','Grassy']::text[], ARRAY['Rich in Antioxidants','Improves Focus']::text[], '#7BA05B', 0, 10, 20, 25, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Shincha', 'shincha', '', '新茶', 'Japanese green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Shoumei tea', 'shoumei-tea', '', '壽眉', 'Chinese white tea', '', 'white', 'true_tea', 'low', 80, 3, 3, '', '{}'::text[], '{}'::text[], '#C8C4B0', 10, 5, 20, 10, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Shui Jin Gui tea', 'shui-jin-gui-tea', '', '水金龜', 'lighter Wuyi oolong tea', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Silver Needle (Bai Hao Yin Zhen)', 'silver-needle', '', '白毫银针', 'White Hair Silver Needle — the highest grade and most expensive white tea. Only unopened leaf buds from the Da Bai cultivar are used. Lightly oxidized, sun-withered up to 3 days. Smell of fresh-cut hay; sweet, vegetal, delicate flavor. Slightly viscous pale yellow liquor with floating white hairs. Steeping should be longer than other white teas, up to 5 minutes per brew.', 'Fujian, China', 'white', 'true_tea', 'low', 77, 5, 3, 'Use 3g per 200ml of water at 75–80°C. Steep for 3–5 minutes — white tea is forgiving and won''t turn bitter. The downy buds can be re-steeped up to 3 times. Excellent cold-brewed: 8g per litre of cold water for 8 hours in the refrigerator.', ARRAY['Floral','Sweet','Fruity']::text[], ARRAY['Rich in Antioxidants','Reduces Inflammation','Boosts Immune System']::text[], '#C8C4B0', 10, 5, 7, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Sollip-Cha', 'pine-needle-tea', '', '솔잎차', 'traditional Korean beverage made by infusing pine needles', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ssuk-Cha', 'ssuk-cha', '', '쑥차', 'traditional Korean beverage made by infusing the dried leaves of mugwort', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Sujeonggwa', 'sujeonggwa', '', '수정과', 'traditional Korean beverage made with ginger, dried persimmon, and cinnamon; often garnished with pine nuts too', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Taiping houkui', 'taiping-houkui', '', '太平猴魁', 'green tea', '', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tamaryokucha', 'tamaryokucha', '', '玉緑茶', 'Japanese green tea', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tencha', 'tencha', '', '碾茶', 'Japanese green tea, base of matcha', 'Japan', 'green', 'true_tea', 'medium', 75, 2, 3, '', '{}'::text[], '{}'::text[], '#7BA05B', 0, 10, 20, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tie Guan Yin (Iron Goddess of Mercy)', 'tie-guan-yin', '', '铁观音', 'Named after the Buddhist goddess of mercy, this celebrated Fujian oolong is lightly oxidised and tightly rolled into small jade-green pearls. It opens to reveal a delicate, orchid-like floral aroma with a creamy, lingering sweetness that has made it China''s favourite oolong.', 'Anxi, Fujian, China', 'oolong', 'true_tea', 'medium', 90, 3, 5, 'Use 5g per 100ml at 90–95°C. Perform a quick rinse (10 seconds) to open the tightly rolled leaves. Steep for 45–90 seconds per infusion. The tightly rolled leaves will continue to slowly unfurl over 5–7 gongfu infusions, evolving in flavour with each.', ARRAY['Floral','Creamy','Sweet']::text[], ARRAY['Rich in Antioxidants','Boosts Heart Health','Reduces Stress & Anxiety']::text[], '#D4852A', 50, 50, 45, 7, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tieguanyin', 'tieguanyin', '', '鐵觀音', 'famous oolong tea, one of top-10 Chinese teas', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tieluohan tea', 'tieluohan-tea', '', '鉄羅漢', 'type of Wuyi tea', '', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 40, 30, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tsheringma tea', 'tsheringma-tea', '', '', 'Herbal tea made in Bhutan', 'Bhutan', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 0, 20, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Tung-ting tea', 'tung-ting-tea', '', '凍頂', 'oolong from Taiwan', 'Taiwan', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 50, 50, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Turmeric Tea', 'turmeric-tea', '', '', 'Japanese tea made from turmeric', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Ureshino Tea', 'ureshino-tea', '', '嬉野茶', 'tea from the region of Ureshino, Saga Prefecture, Japan', 'Japan', 'oolong', 'true_tea', 'medium', 90, 3, 5, '', '{}'::text[], '{}'::text[], '#D4852A', 40, 30, 50, 30, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Wakoucha', 'wakoucha', '', '和紅茶', 'black tea that is produced in Japan', 'Japan', 'black', 'true_tea', 'high', 95, 4, 2, '', '{}'::text[], '{}'::text[], '#8B4513', 90, 70, 62, 45, 'default', 'Teapp', NULL, TRUE, NULL),
  ('White Peony (Bai Mu Dan)', 'white-peony', '', '白牡丹', 'White peony tea made from one bud and two young leaves of the Da Bai cultivar. Slightly oxidized, sun-withered for 1-3 days. Mild peony and floral aroma; fruity flavor, fuller than Silver Needle but less strong than Shou Mei. Pale green or golden liquor. Best brewed with mineral water at 70-80°C.', 'Fujian, China', 'white', 'true_tea', 'low', 75, NULL, 3, 'Use 2–3g per 200ml of water at 75–85°C. Steep for 3–5 minutes. White teas are very forgiving with time. Can be re-steeped 2–3 times. A wonderful entry point into white teas — more flavourful than Silver Needle but still delicate.', ARRAY['Floral','Sweet','Fruity']::text[], ARRAY['Rich in Antioxidants','Reduces Inflammation']::text[], '#C8C4B0', 10, 5, 7, 5, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Yesheng Bai Ya tea', 'yesheng-bai-ya-tea', '', '野生白芽', 'Chinese white tea', 'People''s Republic of China', 'white', 'true_tea', 'low', 80, 3, 3, '', '{}'::text[], '{}'::text[], '#C8C4B0', 10, 5, 20, 10, 'default', 'Teapp', NULL, TRUE, NULL),
