  ('Yuja-Cha', 'yuja-cha', '', '유자차', 'traditional Korean beverage made by diluting yuzu marmalade with water', '', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
  ('Yulmu-Cha', 'yulmu-cha', '', '율무차', 'beverage made with the flour of roasted grains of Job''s tears', 'Korea', 'tisane', 'tisane', 'none', 100, 5, 2, '', '{}'::text[], '{}'::text[], '#C0856A', 40, 30, 25, 20, 'default', 'Teapp', NULL, TRUE, NULL),
